// تقيمات المتجر يوجد css
document.addEventListener("DOMContentLoaded", function () {

    const bannerSection = document.querySelector("section.py-10");
    if (!bannerSection) return;

    const section = document.createElement("section");
    section.className = "custom-know-more";

   section.innerHTML = `
    <div class="know-wrapper">
        <h3 class="know-title">فخورين بما حققناه معكم</h3>

        <div class="injazes">

            <div class="injaz">
                <img src="https://up6.cc/2026/02/177162603174561.gif">
                <div class="injaz_count_outer font-bold text-xl flex justify-center">
                    <salla-counter on="true" count_to="20563" speed="50" runonviewonly="true" class="counter-container">
                        <span class="injaz_plus">+</span>
                        <div class="injaz_count dm-text-main is-num">20563</div>
                        <span class="injaz_suffix">طلب</span>
                    </salla-counter>
                </div>
                <div class="injaz-label">عميل للمتجر</div>
            </div>

            <div class="injaz">
                <img src="https://up6.cc/2026/02/177162603175982.gif">
                <div class="injaz_count_outer font-bold text-xl flex justify-center">
                    <salla-counter on="true" count_to="5" speed="50" runonviewonly="true" class="counter-container">
                        <span class="injaz_plus">+</span>
                        <div class="injaz_count dm-text-main is-num">5</div>
                        <span class="injaz_suffix">سنوات</span>
                    </salla-counter>
                </div>
                <div class="injaz-label">سنوات بإزدهار المتجر</div>
            </div>

            <div class="injaz">
                <img src="https://up6.cc/2026/02/177162603179263.gif">
                <div class="injaz_count_outer font-bold text-xl flex justify-center">
                    <salla-counter on="true" count_to="845" speed="50" runonviewonly="true" class="counter-container">
                        <span class="injaz_plus">+</span>
                        <div class="injaz_count dm-text-main is-num">845</div>
                        <span class="injaz_suffix">عميل</span>
                    </salla-counter>
                </div>
                <div class="injaz-label">طلب</div>
            </div>

        </div>
    </div>
`;

    bannerSection.insertAdjacentElement("afterend", section);

    const injazItems = document.querySelectorAll(".injaz");
    const counters = document.querySelectorAll(".injaz-count");

    const observer = new IntersectionObserver(entries => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {

                injazItems.forEach((item, i) => {
                    setTimeout(() => item.classList.add("show"), i * 200);
                });

                counters.forEach(counter => {
                    const target = +counter.getAttribute("data-count");
                    let count = 0;
                    const speed = target / 100;

                    const updateCount = () => {
                        if (count < target) {
                            count += speed;
                            counter.innerText = Math.floor(count);
                            requestAnimationFrame(updateCount);
                        } else {
                            counter.innerText = target;
                        }
                    };

                    updateCount();
                });

                observer.disconnect();
            }
        });
    }, { threshold: 0.4 });

    observer.observe(section);

});






