    // ألوان الدائرة متعددة
    if(s.ringColors.length === 3){
      ring.style.borderTop = `3px solid ${s.ringColors[0]}`;
      ring.style.borderRight = `3px solid ${s.ringColors[1]}`;
      ring.style.borderBottom = `3px solid ${s.ringColors[2]}`;
    } else {
      ring.style.border = `2px solid ${s.ringColors[0]}`;
      ring.style.borderTopColor = 'transparent';
      ring.style.borderBottomColor = 'transparent';
    }

    a.appendChild(ring);

    // الصورة لكل الأيقونات
    const img = document.createElement('img');
    img.src = s.imgSrc;
    img.style.width = s.imgWidth;
    img.style.height = s.imgHeight;
    img.style.zIndex = 2;
    a.appendChild(img);

    // Hover effect
    a.addEventListener('mouseenter', ()=>{
      a.style.transform = 'translateY(-10px) rotateX(20deg)';
    });
