//باقات المنتجات الرقمية
document.addEventListener("DOMContentLoaded", function () {

    const images = [
        "https://up6.cc/2026/02/17718452705361.png",
        "https://up6.cc/2026/02/177184527057552.png",
        "https://up6.cc/2026/02/177184527062123.png"
    ];

    // نبحث عن عنوان القسم
    const title = [...document.querySelectorAll("h2.title")]
        .find(el => el.textContent.includes("منتجات رقمية اشتراكات"));

    if (!title) return;

    const section = title.closest("section");
    if (!section) return;

    const cards = section.querySelectorAll(".link-card");

    cards.forEach((card, index) => {
        const img = card.querySelector("img");

        if (img && images[index]) {
            img.src = images[index];
        }
    });

});
